function normalPostalZone(value) {
  const match = /^(\d{4})-(\d{3})$/.exec(String(value || '').trim());
  if (!match) return null;
  const exact = EXACT_MUNICIPALITY_CP7[match[0]];
  if (exact) return exact;
  const group = SINGLE_MUNICIPALITY_CP4[match[1]];
  if (!group) return null;
  const cp3 = Number(match[2]);
  return group[1].some(([from, to]) => cp3 >= from && cp3 <= to) ? group[0] : null;
}
